mobile:['Android-style app','Material You list, FAB and bottom bar',{'index.html':'<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Android style app</title>\n<link rel="stylesheet" href="style.css">\n</head>\n<body>\n<header><h1>Inbox</h1></header>\n<main id="list"></main>\n<button id="fab">+ Compose</button>\n<nav><a class="on">Home</a><a>Search</a><a>Settings</a></nav>\n<script src="app.js"></script>\n</body>\n</html>\n','style.css':'body{margin:0;font-family:system-ui,sans-serif;background:#fef7ff;color:#1d1b20;padding-bottom:90px}\nheader{padding:48px 24px 16px}h1{margin:0;font-size:32px;font-weight:400}\n.card{margin:8px 16px;padding:16px 20px;border-radius:24px;background:#f3edf7}\n.card small{color:#625b71;display:block}\n#fab{position:fixed;right:20px;bottom:100px;border:0;border-radius:18px;padding:18px 22px;background:#eaddff;color:#21005d;font-size:15px;font-weight:500}\nnav{position:fixed;left:0;right:0;bottom:0;display:flex;justify-content:space-around;padding:14px 0 20px;background:#f3edf7}\nnav a{padding:6px 22px;border-radius:16px;color:#49454f}nav a.on{background:#e8def8;color:#1d1b20}\n','app.js':'const list=document.getElementById("list");\nlet n=0;\nfunction add(t){n++;const d=document.createElement("div");d.className="card";d.innerHTML="<b>"+t+"</b><small>Message "+n+"</small>";list.prepend(d)}\n["Welcome","Your first message","Tap Compose to add more"].forEach(add);\ndocument.getElementById("fab").onclick=()=>add("New message");\n'}],
landing:['Landing page','Hero, features and footer',{'index.html':'<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>My product</title>\n<link rel="stylesheet" href="style.css">\n</head>\n<body>\n<header><b>Brand</b><a href="#features">Features</a></header>\n<section class="hero"><h1>Build something great</h1><p>A simple landing page you can edit.</p><a class="cta" href="#features">Learn more</a></section>\n<section id="features"><div><h3>Fast</h3><p>Loads instantly.</p></div><div><h3>Simple</h3><p>Plain HTML and CSS.</p></div><div><h3>Yours</h3><p>Change anything.</p></div></section>\n<footer>Made with ScriptX-Engine</footer>\n</body>\n</html>\n','style.css':'body{margin:0;font-family:system-ui,sans-serif;color:#1d1b32}\nheader{display:flex;justify-content:space-between;padding:20px 28px}header a{color:#6750a4}\n.hero{padding:70px 28px;text-align:center;background:#eaddff}.hero h1{font-size:40px;margin:0 0 10px}\n.cta{display:inline-block;margin-top:18px;padding:14px 30px;border-radius:99px;background:#6750a4;color:#fff;text-decoration:none}\n#features{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px;padding:32px 28px}\n#features div{background:#f3edf7;border-radius:24px;padding:22px}\nfooter{text-align:center;padding:30px;color:#625b71}\n'}],
todo:['To-do app','Add and complete tasks',{'index.html':'<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>To-do</title>\n<style>body{font-family:system-ui,sans-serif;max-width:420px;margin:0 auto;padding:24px}input{padding:12px 16px;border-radius:99px;border:1px solid #ccc;width:65%}button{padding:12px 18px;border:0;border-radius:99px;background:#6750a4;color:#fff}li{padding:10px 0;cursor:pointer}li.done{text-decoration:line-through;opacity:.5}</style>\n</head>\n<body>\n<h1>To-do</h1>\n<input id="t" placeholder="New task"> <button id="add">Add</button>\n<ul id="l"></ul>\n<script src="app.js"></script>\n</body>\n</html>\n','app.js':'const l=document.getElementById("l"),t=document.getElementById("t");\ndocument.getElementById("add").onclick=()=>{if(!t.value)return;const i=document.createElement("li");i.textContent=t.value;i.onclick=()=>i.classList.toggle("done");l.appendChild(i);console.log("added",t.value);t.value=""};\n'}],
game:['Tap game','A small canvas game',{'index.html':'<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="utf-8">\n<meta name="viewport" content="width=device-width, initial-scale=1">\n<title>Tap game</title>\n<style>body{margin:0;display:grid;place-items:center;min-height:100vh;background:#f3efff}canvas{background:#fff;border-radius:24px;max-width:94vw}</style>\n</head>\n<body>\n<canvas id="c" width="300" height="300"></canvas>\n<script src="app.js"></script>\n</body>\n</html>\n','app.js':'const c=document.getElementById("c"),x=c.getContext("2d");\nlet s=0,d={x:150,y:150};\nfunction draw(){x.clearRect(0,0,300,300);x.fillStyle="#6750a4";x.beginPath();x.arc(d.x,d.y,22,0,7);x.fill();x.fillStyle="#000";x.fillText("Score: "+s,10,20)}\nc.onclick=e=>{const r=c.getBoundingClientRect(),px=(e.clientX-r.left)*300/r.width,py=(e.clientY-r.top)*300/r.height;if(Math.hypot(px-d.x,py-d.y)<24){s++;d={x:30+Math.random()*240,y:30+Math.random()*240};console.log("score",s)}draw()};\ndraw();\n'}],
