async function dec(s){const u=unb64u(s.slice(1));return new TextDecoder().decode(s[0]==='z'?await pipe(u,DecompressionStream):u)}
const iceDone=pc=>new Promise(r=>{if(pc.iceGatheringState==='complete')return r();const f=()=>{if(pc.iceGatheringState==='complete'){pc.removeEventListener('icegatheringstatechange',f);r()}};pc.addEventListener('icegatheringstatechange',f);setTimeout(r,3500)});
