async function prepData(){for(const k in F){const d=F[k].d;if(typeof d!=='string'&&!DU[k+':'+F[k].t])DU[k+':'+F[k].t]=await new Promise(r=>{const fr=new FileReader();fr.onload=()=>r(fr.result);fr.readAsDataURL(d)})}}
async function pushRemote(){if(LIVE.state!=='open'||!LIVE.dc||LIVE.dc.readyState!=='open'||!cur)return;await prepData();sendBig(LIVE.dc,JSON.stringify({html:build(PV.page,1)}))}
function liveStop(){try{LIVE.dc&&LIVE.dc.close();LIVE.pc&&LIVE.pc.close()}catch(e){}LIVE={state:'idle'}}
async function liveStart(){liveStop();LIVE={state:'wait'};render();try{const pc=new RTCPeerConnection(ICE),dc=pc.createDataChannel('sx');LIVE.pc=pc;LIVE.dc=dc;
 dc.onopen=()=>{LIVE.state='open';toast('Phone connected');render();pushRemote()};dc.onclose=()=>{if(LIVE.state==='open'){LIVE={state:'idle'};toast('Phone disconnected');render()}};
 dc.onmessage=e=>{try{const m=JSON.parse(e.data);if(m.c)plog(m.c.t,'[phone] '+m.c.m);if(m.nav){const k=rs(m.nav,PV.page);if(k&&fd(k)!=null){PV.page=k;pushRemote()}}}catch(x){}};
 await pc.setLocalDescription(await pc.createOffer());await iceDone(pc);LIVE.link=base()+'#/receive/'+await enc(JSON.stringify(pc.localDescription));LIVE.state='offer'}catch(e){LIVE={state:'idle'};toast('This browser cannot start a connection.')}render()}
